"use client";

import {
  type ButtonHTMLAttributes,
  createContext,
  type HTMLAttributes,
  type MouseEvent,
  type ReactNode,
  type RefObject,
  use,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import type { Align, Side } from "../interaction/floating";
import { useDismiss, useFloating, usePresence } from "../interaction/use-floating";
import { cx } from "../utils/cx";
import { Slot } from "../utils/slot";

type PopoverContextValue = {
  open: boolean;
  setOpen: (open: boolean) => void;
  triggerRef: RefObject<HTMLElement | null>;
  contentId: string;
  side: Side;
  align: Align;
  offset: number;
};
const PopoverContext = createContext<PopoverContextValue | null>(null);

function usePopover(part: string): PopoverContextValue {
  const ctx = use(PopoverContext);
  if (!ctx) throw new Error(`<${part}> must be inside <Popover>`);
  return ctx;
}

export type PopoverProps = {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  side?: Side;
  align?: Align;
  offset?: number;
  children: ReactNode;
};

/**
 * A non-modal panel anchored to its trigger. It lives in the top layer (native `popover`), is positioned by the
 * floating engine (flips and stays on screen), and closes on Escape or an outside press. Use `Dialog` when the
 * content must block the page, `DropdownMenu` for a list of actions.
 */
export function Popover({
  open: controlled,
  defaultOpen = false,
  onOpenChange,
  side = "bottom",
  align = "start",
  offset = 6,
  children,
}: PopoverProps) {
  const [uncontrolled, setUncontrolled] = useState(defaultOpen);
  const open = controlled ?? uncontrolled;
  const setOpen = useCallback(
    (next: boolean) => {
      if (controlled === undefined) setUncontrolled(next);
      onOpenChange?.(next);
    },
    [controlled, onOpenChange],
  );
  const triggerRef = useRef<HTMLElement>(null);
  const contentId = useId();
  return (
    <PopoverContext value={{ open, setOpen, triggerRef, contentId, side, align, offset }}>{children}</PopoverContext>
  );
}

export function PopoverTrigger({
  asChild,
  onClick,
  ...rest
}: ButtonHTMLAttributes<HTMLButtonElement> & { asChild?: boolean }) {
  const { open, setOpen, triggerRef, contentId } = usePopover("PopoverTrigger");
  const Comp = asChild ? Slot : "button";
  return (
    <Comp
      {...(asChild ? {} : { type: "button" as const })}
      {...(rest as object)}
      ref={triggerRef as RefObject<HTMLButtonElement>}
      aria-haspopup="dialog"
      aria-expanded={open}
      aria-controls={open ? contentId : undefined}
      onClick={(e: MouseEvent<HTMLButtonElement>) => {
        onClick?.(e);
        if (!e.defaultPrevented) setOpen(!open);
      }}
    />
  );
}

export type PopoverContentProps = HTMLAttributes<HTMLDivElement> & {
  "aria-label"?: string;
  "aria-labelledby"?: string;
};

export function PopoverContent({ className, children, ...rest }: PopoverContentProps) {
  const { open, setOpen, triggerRef, contentId, side, align, offset } = usePopover("PopoverContent");
  const ref = useRef<HTMLDivElement>(null);
  const { present, state } = usePresence(open);
  useFloating(present, triggerRef, ref, { side, align, offset });
  const close = useCallback(() => setOpen(false), [setOpen]);
  const refocus = useCallback(() => triggerRef.current?.focus(), [triggerRef]);
  useDismiss(open, triggerRef, ref, close, refocus);
  const wasOpen = useRef(false);
  useEffect(() => {
    if (open) {
      wasOpen.current = true;
      ref.current?.focus({ preventScroll: true });
    } else if (wasOpen.current) {
      wasOpen.current = false;
      // closed from inside (a choice was made): put focus back on the trigger, as Escape does
      if (ref.current?.contains(document.activeElement)) triggerRef.current?.focus();
    }
  }, [open, triggerRef]);
  if (!present) return null;
  return (
    <div
      {...rest}
      ref={ref}
      data-state={state}
      inert={state === "closed" || undefined}
      id={contentId}
      popover="manual"
      role="dialog"
      tabIndex={-1}
      className={cx("hm-floating hm-popover", className)}
    >
      {children}
    </div>
  );
}
